n['controls'].append({'id':'RUSTHOMOLOGY-C009','rule':'independent_distance_and_f2_controls','status':'countermodels_and_512_matrix_ranks_confirmed','evidence':[ev('bottleneck_distance.rs',8,45),ev('wasserstein_distance.rs',8,24),ev('matrix_reduction.rs',38,66),ev('twist_algorithm.rs',96,167),ev('representative_cycle.rs',14,40)],'helper':{'path':str(a.file('_probe09.py').relative_to(a.ROOT)).replace('\\','/'),'sha256':a.sha(a.file('_probe09.py'))},'receipt':{'path':str(a.file('_probe09.json').relative_to(a.ROOT)).replace('\\','/'),'sha256':a.sha(a.file('_probe09.json'))},'limits':'Independent Python exact finite and floating representation controls; no native execution.'})
